<script setup>
import {usePreferencesTranslator} from "../preferences/preferences-state.js";
const uiLabel=usePreferencesTranslator();
import TablePanel from '../../shared/components/TablePanel.vue';

import { vMoney } from './money-input.js';
import {computed,inject,onMounted,reactive,ref,watch} from 'vue';
import {amount,errorText,financeKey,minor,money,positive,statuses,time} from './finance-model.js';
import FinanceDialog from './FinanceDialog.vue';
import FinancePagination from './FinancePagination.vue';
const vm=inject(financeKey),invoices=vm.resource('invoices'),account=ref(''),status=ref(''),detail=ref(null),createOpen=ref(false),settleOpen=ref(null);
const draft=reactive({account_id:'',kind:'receivable',supplier:'',amount:'',reference:'',service:'',currency:''}),settlement=reactive({amount:'',method:'',reference:''}),createKey=vm.key(),settleKey=vm.key();
const visibleAccounts=computed(()=>vm.accounts.value.filter(row=>row.type!=='system'));
function load(page=1){if(vm.emptyScope()){invoices.dispose();return;}return invoices.load(vm.recordParameters({account_id:account.value,status:status.value,per_page:25,page}));}
watch([vm.service,vm.currency,account,status],()=>{detail.value=null;load();});watch(vm.filters,()=>{detail.value=null;load();},{deep:true});onMounted(()=>load());
const canSettle=row=>row.status!=='cancelled'&&vm.can('invoices.settle') && positive(row.remaining) && (row.kind==='payable' || (row.source_type==='digital_topup'&&(vm.admin.value||Number(row.creditor_account_id)===Number(vm.ownId.value))) || (vm.admin.value && vm.ownVisible.value && vm.can('wallets.deposit')));
function openCreate(){vm.error.value='';Object.assign(draft,{account_id:account.value || String(vm.ownId.value),kind:'receivable',supplier:'',amount:'',reference:'',service:vm.service.value || 'cash',currency:vm.currency.value});createOpen.value=true;}
async function create(){try{const payload={account_id:Number(draft.account_id),kind:draft.kind,service:draft.service,currency:draft.currency,amount:amount(draft.amount),reference:draft.reference.trim(),...(draft.kind==='payable'?{supplier:draft.supplier.trim()}:{})};const response=await vm.execute(payload,createKey,body=>vm.api.create('invoices',body),'تم تسجيل الفاتورة.');if(response){createOpen.value=false;await vm.refresh();await load();}}catch(failed){vm.error.value=errorText(failed);}}
function openSettle(row){vm.error.value='';settleOpen.value=row;Object.assign(settlement,{amount:row.remaining,method:'',reference:''});}
async function settle(){try{const row=settleOpen.value,value=amount(settlement.amount);if(minor(value)>minor(row.remaining))throw new Error('مبلغ التحصيل يتجاوز المتبقي من الفاتورة.');const response=await vm.execute({version:row.version,amount:value,reference:`${settlement.method}: ${settlement.reference.trim()}`},settleKey,body=>vm.api.action('invoices',row.id,'settle',body),'تم تسجيل التحصيل / التسديد.');if(response){settleOpen.value=null;detail.value=null;await vm.refresh();await load();}}catch(failed){vm.error.value=errorText(failed);}}
</script>
<template><div class="card wallet-invoices"><div class="cardhead"><label>حساب الوكيل<select v-model="account"><option value="">الكل</option><option v-for="row in visibleAccounts" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>حالة الفاتورة<select v-model="status"><option value="">كل الحالات</option><option v-for="state in ['unpaid','partial','paid']" :key="state" :value="state">{{statuses[state]}}</option></select></label><button v-if="vm.can('invoices.create')" class="btn" :disabled="vm.busy.value" @click="openCreate">تسجيل فاتورة</button></div><p v-if="invoices.state.error" class="notice warn" role="alert">{{invoices.state.error}}</p><p v-if="invoices.state.loading" class="read-loading caption">جارٍ تحميل الفواتير…</p><TablePanel :start="(invoices.state.meta.current_page-1)*25+1" class="tablewrap"><table><thead><tr><th>الفاتورة</th><th>الوكيل</th><th>الكمية</th><th>سعر التحميل</th><th>القيمة</th><th v-if="vm.can('data.profit')">الربح المتوقع</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody><tr v-for="row in invoices.state.rows" :key="row.id"><td>{{row.id}}<small class="caption">{{row.kind==='payable'?'مستحق للمورد':'ذمة مدينة'}}</small></td><td>{{row.account_name || vm.name(row.account_id)}}</td><td>{{row.quantity ?? '—'}}</td><td>{{money(row.load_price)}}</td><td>{{money(row.amount)}} {{vm.currencyLabel(row.currency)}}</td><td v-if="vm.can('data.profit')">{{money(row.profit)}} {{row.contract || ''}}</td><td><span class="badge">{{statuses[row.status] || row.status}}</span></td><td><div class="actions"><button class="btn small" @click="detail=detail?.id===row.id?null:row">التفاصيل</button><button v-if="canSettle(row)" class="btn small primary" :disabled="vm.busy.value" @click="openSettle(row)">{{row.kind==='payable'?'تسديد':'تسجيل تحصيل'}}</button></div></td></tr><tr v-if="!invoices.state.rows.length && !invoices.state.loading"><td :colspan="vm.can('data.profit')?8:7" class="empty">لا توجد فواتير مطابقة</td></tr></tbody></table></TablePanel><FinancePagination :meta="invoices.state.meta" :busy="invoices.state.loading" @page="load" /><section v-if="detail" class="funding-record-detail"><div class="funding-settings-heading"><h4>تفاصيل الفاتورة · {{detail.id}}</h4><button class="btn small" @click="detail=null">إغلاق التفاصيل</button></div><dl class="account-fields"><div><dt>حساب الوكيل</dt><dd>{{detail.account_name || vm.name(detail.account_id)}}</dd></div><div><dt>النوع</dt><dd>{{detail.kind==='payable'?'مستحق للمورد':'ذمة مدينة'}}</dd></div><div><dt>القيمة</dt><dd>{{money(detail.amount)}} {{vm.currencyLabel(detail.currency)}}</dd></div><div><dt>المسدد</dt><dd>{{money(detail.paid)}}</dd></div><div><dt>المتبقي بعد التحصيل</dt><dd>{{money(detail.remaining)}}</dd></div><div><dt>المورد</dt><dd>{{detail.supplier || '—'}}</dd></div><div><dt>المحفظة</dt><dd>{{uiLabel(vm.serviceName(detail.service))}}</dd></div><div><dt>رقم السند</dt><dd>{{detail.reference}}</dd></div><div><dt>وقت الفاتورة</dt><dd>{{time(detail.created_at)}}</dd></div><div><dt>نفذ التسجيل</dt><dd>{{detail.creator_name || '#'+detail.creator_id}}</dd></div></dl></section></div>
  <FinanceDialog :open="createOpen" title="تسجيل فاتورة" :busy="vm.busy.value" @close="createOpen=false"><form @submit.prevent="create"><div class="formgrid"><label>حساب الوكيل<select v-model="draft.account_id" required><option v-for="row in vm.options.accounts" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>نوع الفاتورة<select v-model="draft.kind"><option value="receivable">ذمة مدينة</option><option value="payable">مستحق للمورد</option></select></label><label v-if="draft.kind==='payable'">المورد<input v-model="draft.supplier" required maxlength="160"></label><label>المحفظة<select v-model="draft.service" required><option v-for="row in vm.options.services" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>القيمة<input v-model="draft.amount" type="text" inputmode="decimal" v-money required></label><label>رقم السند<input v-model="draft.reference" maxlength="200" required></label></div><p v-if="vm.error.value" class="notice warn" role="alert">{{vm.error.value}}</p><div class="actions"><button class="btn primary" :disabled="vm.busy.value || !positive(draft.amount) || !draft.reference.trim()">تسجيل فاتورة</button><button type="button" class="btn" :disabled="vm.busy.value" @click="createOpen=false">إلغاء</button></div></form></FinanceDialog>
  <FinanceDialog :open="!!settleOpen" :title="settleOpen?.kind==='payable'?'تسديد فاتورة':'تسجيل تحصيل'" :busy="vm.busy.value" @close="settleOpen=null"><template v-if="settleOpen"><p>{{vm.name(settleOpen.account_id)}} · الفاتورة #{{settleOpen.id}}</p><p class="notice">المتبقي بعد التحصيل: {{money(settleOpen.remaining)}} {{vm.currencyLabel(settleOpen.currency)}}</p><form @submit.prevent="settle"><div class="formgrid"><label>{{settleOpen.kind==='payable'?'مبلغ التسديد':'مبلغ التحصيل'}}<input v-model="settlement.amount" type="text" inputmode="decimal" v-money required></label><label>الطريقة<select v-model="settlement.method" required><option value="" disabled>اختر طريقة التحصيل</option><option value="مندوب">مندوب</option><option value="QiCard">QiCard</option><option value="تحويل مصرفي">تحويل مصرفي</option></select></label><label>رقم السند<input v-model="settlement.reference" maxlength="170" required></label></div><p v-if="vm.error.value" class="notice warn" role="alert">{{vm.error.value}}</p><div class="actions"><button class="btn primary" :disabled="vm.busy.value || !positive(settlement.amount) || !settlement.method || !settlement.reference.trim()">{{vm.busy.value?'جارٍ التسجيل…':settleOpen.kind==='payable'?'تسجيل تسديد':'تسجيل تحصيل'}}</button><button type="button" class="btn" :disabled="vm.busy.value" @click="settleOpen=null">إلغاء</button></div></form></template></FinanceDialog>
</template>
